// Bloques A-G según Tabla 1 (128 dimensiones)
pub const BLOCK_A: std::ops::Range<usize> = 0..16;   // Identity
pub const BLOCK_B: std::ops::Range<usize> = 16..24;  // Resources
pub const BLOCK_C: std::ops::Range<usize> = 24..32;  // Entropy
pub const BLOCK_D: std::ops::Range<usize> = 32..48;  // Operations
pub const BLOCK_E: std::ops::Range<usize> = 48..64;  // Channels
pub const BLOCK_F: std::ops::Range<usize> = 64..96;  // Attractor
pub const BLOCK_G: std::ops::Range<usize> = 96..128; // Intelligence

#[derive(Clone, Debug)]
pub struct StateVector {
    pub  [f64; 128],
}

impl StateVector {
    pub fn new() -> Self {
        Self {  [0.0; 128] }
    }

    // Acceso semántico a bloques
    pub fn trust(&self) -> f64 { self.data[13] }
    pub fn entropy(&self) -> f64 { self.data[24] }
    pub fn hrest(&self) -> f64 { self.data[25] }
    pub fn delta_h(&self) -> f64 { self.data[26] }
    pub fn stasis_cos(&self) -> f64 { self.data[27] }
    pub fn cpu_pressure(&self) -> f64 { self.data[16] }

    // Métrica de viabilidad (θviable = 0.70, §2.2)
    pub fn viable(&self) -> bool {
        self.stasis_cos() >= 0.70
    }

    // Similitud coseno (Eq. 2)
    pub fn cosine_similarity(&self, other: &StateVector) -> f64 {
        let dot: f64 = self.data.iter().zip(other.data.iter()).map(|(a, b)| a * b).sum();
        let norm_a = self.data.iter().map(|x| x * x).sum::<f64>().sqrt();
        let norm_b = other.data.iter().map(|x| x * x).sum::<f64>().sqrt();
        if norm_a == 0.0 || norm_b == 0.0 { return 0.0; }
        dot / (norm_a * norm_b)
    }
}
```

