// Función de Lyapunov (Eq. 10)
pub struct LyapunovTracker {
    pub alpha: f64, pub beta: f64, pub gamma: f64, pub delta: f64,
    pub prev_l: f64,
    pub cumulative_dl: f64,
    pub tick_count: u64,
}

impl LyapunovTracker {
    pub fn new() -> Self {
        Self {
            alpha: 0.4, beta: 0.3, gamma: 0.2, delta: 0.1,
            prev_l: 1.0, cumulative_dl: 0.0, tick_count: 0,
        }
    }

    // L(x) = α(1-cos) + β(H/Hmax) + γ·max(0, B-Bavail) + δ·ReLU(Hrest_drift)
    pub fn compute(&self, sv: &StateVector, hmax: f64, b_avail: f64) -> f64 {
        let cos_term = 1.0 - sv.stasis_cos();
        let ent_term = sv.entropy() / hmax.max(1e-6);
        let budget_term = (sv.cpu_pressure() - b_avail).max(0.0);
        let senes_term = (sv.hrest() - 0.4).max(0.0); // Hrest baseline §9.3

        self.alpha * cos_term + self.beta * ent_term + self.gamma * budget_term + self.delta * senes_term
    }

    pub fn tick(&mut self, current_l: f64) -> f64 {
        let dl = current_l - self.prev_l;
        self.cumulative_dl += dl;
        self.prev_l = current_l;
        self.tick_count += 1;
        dl // proxy por tick (Eq. 12)
    }
}
```

