use rand::distributions::Distribution;
use rand::distributions::Normal;
use crate::state_vector::StateVector;
use crate::lyapunov::LyapunovTracker;
use crate::abreath::AbreathAxiom;
use crate::subsystems::{s1_operations, s3_control, s4_intelligence, s5_policy};

pub struct Experiment {
    pub name: String,
    pub ticks: u64,
    pub checkpoint_interval: u64,
}

impl Experiment {
    pub fn run(&self, mut sv: StateVector, ref_sv: StateVector, mut lyap: LyapunovTracker) {
        let mut rng = rand::thread_rng();
        let normal = Normal::new(0.0, 1.0).unwrap();
        let hmax = 0.85 * (4.0_f64.log2()); // Hmax ≈ 1.700 bits (§9.4)

        println!("🔬 Running: {} | {} ticks", self.name, self.ticks);

        for t in 0..self.ticks {
            // 1. S1-S5 deterministic update (f₀)
            s1_operations::update(&mut sv);
            s3_control::allocate_resources(&mut sv, 0.6);
            s4_intelligence::detect_drift(&mut sv, &ref_sv);
            s5_policy::enforce_ceiling(&mut sv);

            // 2. Abreath stochastic noise (Eq. 3)
            let sigma = AbreathAxiom::sigma(&sv);
            for dim in 0..128 {
                let noise = normal.sample(&mut rng) * sigma;
                sv.data[dim] += noise * 0.001; // scaling para estabilidad numérica
            }

            // 3. Lyapunov tracking
            let l = lyap.compute(&sv, hmax, 1.0);
            let dl = lyap.tick(l);

            // 4. Safety halt (thermal ceiling mock)
            if t % self.checkpoint_interval == 0 {
                let cos = sv.cosine_similarity(&ref_sv);
                sv.data[27] = cos; // update stasis_cos cache
                println!("t={:>6} | cos={:.4} | dL={:.5} | trust={:.3} | viable={}", 
                         t, cos, dl, sv.trust(), sv.viable());
            }

            if !sv.viable() {
                eprintln!("⚠️ VIABILITY BREACH at t={}. Halting.", t);
                break;
            }
        }
    }
}
```

