```rust
// src/instantiation.rs
use crate::state_vector::{StateVector, Block};
use crate::omega::{OmegaValidator, AxiomSet};
use crate::cgroup::CgroupV2Bridge;

pub struct InstantiationGate {
    pub omega: OmegaValidator,
    pub cgroup: CgroupV2Bridge,
    pub schema_registry: SchemaRegistry,
}

pub struct UnitSpec {
    pub id: String,
    pub purpose: String,           // Para Ω_A0 check
    pub cpu_weight: u64,           // cgroup v2
    pub memory_max: u64,
    pub io_weight: u64,
    pub telemetry_schema: String,  // events.jsonl schema ref
    pub params_schema: String,     // params.json schema ref
}

pub enum InstantiationError {
    AxiomViolation(&'static str),  // "A0", "A0.1", "A3", "A5"
    ResourceExhaustion,
    SchemaNotFound,
}

impl InstantiationGate {
    pub fn register_unit(&self, spec: UnitSpec) -> Result<UnitHandle, InstantiationError> {
        // 1. Verificar Ω_A0/A0.1 (ética como estabilidad estructural)
        if !self.omega.check_purpose(&spec.purpose)? {
            return Err(InstantiationError::AxiomViolation("A0/A0.1"));
        }
        if self.omega.check_coercion_risk(&spec.id)? {
            return Err(InstantiationError::AxiomViolation("A0.1"));
        }

        // 2. Asignar presupuesto físico (Ω_A3) y verificar disponibilidad
        let available = self.cgroup.available_budget()?;
        if spec.cpu_weight > available.cpu || spec.memory_max > available.mem {
            return Err(InstantiationError::ResourceExhaustion);
        }
        let quota = self.cgroup.allocate(
            spec.cpu_weight, spec.memory_max, spec.io_weight
        )?;

        // 3. Validar esquemas de telemetría (C5 semantic validity)
        if !self.schema_registry.exists(&spec.telemetry_schema) {
            return Err(InstantiationError::SchemaNotFound);
        }

        // 4. Configurar canales φ↑/φ↓ y marcar como governed
        let channels = Channels::new(
            spec.telemetry_schema,  // events.jsonl → Block B/C
            spec.params_schema,     // params.json ← Block E
        );

        Ok(UnitHandle {
            id: spec.id,
            quota,
            channels,
            governed: true,
            lifecycle: Lifecycle::Testing,  // requiere conditioning para production
            instantiated_at: std::time::SystemTime::now(),
        })
    }
}

