## 🔹 I. Implementación `AdaptiveClock` (Rust)

Este módulo opera en el loop principal de `vsf-nucleus`. Ajusta `Δt` y la tasa de muestreo `φ↑` sin romper la estabilidad Lyapunov (`E[ΔL] ≤ 0`, Thm 2).

```rust
// src/adaptive_clock.rs
use crate::abreath::AbreathAxiom;
use crate::state_vector::StateVector;

/// Modos de operación del reloj adaptativo
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ClockMode {
    Idle,       // muestreo espaciado, mínimo consumo
    Active,     // muestreo por tick, predictividad completa
    Transition, // rampa suave entre modos
}

/// Condiciones de entrada/salida de modos
pub struct ClockConditions {
    pub drift: f64,          // ||x(t) - x_ref|| o ΔH
    pub load: f64,           // cpu_pressure ∈ [0,1]
    pub task_queue_len: usize,
    pub thermal_c: f64,      // temperatura actual (°C)
}

/// Reloj adaptativo gobernado por axiomas
pub struct AdaptiveClock {
    pub mode: ClockMode,
    pub current_dt: f64,     // paso de tiempo actual (s)
    pub target_dt: f64,      // paso objetivo según modo
    pub ramp_steps: u64,     // ticks para transición completa
    pub tick_counter: u64,
    pub last_phi_up_tick: u64,
    pub phi_up_interval: u64, // ticks entre muestras φ↑
}

// Constantes de estabilidad (calibradas para sustrato OU + Eq. 13)
const DT_MIN: f64 = 0.001;  // 1 ms
const DT_MAX: f64 = 2.0;    // 2 s
const C_STABILITY: f64 = 0.015;
const EPSILON_DRIFT: f64 = 0.005;
const LOAD_THRESHOLD: f64 = 0.10;
const THERMAL_TAU: f64 = 55.0; // °C para activar modo active

impl AdaptiveClock {
    pub fn new() -> Self {
        Self {
            mode: ClockMode::Idle,
            current_dt: DT_MAX,
            target_dt: DT_MAX,
            ramp_steps: 5,
            tick_counter: 0,
            last_phi_up_tick: 0,
            phi_up_interval: 10, // cada 10 ticks en Idle
        }
    }

    /// Selecciona modo según condiciones del sustrato
    pub fn select_mode(&mut self, cond: &ClockConditions) {
        let new_mode = if cond.drift < EPSILON_DRIFT 
            && cond.load < LOAD_THRESHOLD 
            && cond.task_queue_len == 0 
        {
            ClockMode::Idle
        } else if cond.task_queue_len > 0 
            || cond.drift > EPSILON_DRIFT 
            || cond.thermal_c > THERMAL_TAU 
        {
            ClockMode::Active
        } else {
            ClockMode::Transition
        };

        if new_mode != self.mode {
            self.mode = new_mode;
            self.update_target_dt();
        }
    }

    /// Actualiza objetivo de Δt según modo
    fn update_target_dt(&mut self) {
        self.target_dt = match self.mode {
            ClockMode::Idle => DT_MAX,
            ClockMode::Active => DT_MIN,
            ClockMode::Transition => (self.current_dt + DT_MIN) / 2.0,
        };
        self.phi_up_interval = match self.mode {
            ClockMode::Idle => 10,
            ClockMode::Active => 1,
            ClockMode::Transition => 2,
        };
    }

    /// Calcula Δt seguro preservando E[ΔL] ≤ 0 (Thm 2)
    pub fn compute_dt(&mut self, sigma: f64) -> f64 {
        // Cota de estabilidad: Δt ≤ C / (1 + σ²)
        let stability_bound = C_STABILITY / (1.0 + sigma.powi(2));
        let clamped = stability_bound.clamp(DT_MIN, DT_MAX);

        // Rampa suave si está en transición
        if self.mode == ClockMode::Transition && self.ramp_steps > 0 {
            let ramp = self.current_dt + (self.target_dt - self.current_dt) / self.ramp_steps as f64;
            self.current_dt = ramp.min(clamped);
        } else {
            self.current_dt = clamped;
        }
        self.current_dt
    }

    /// Decide si emitir telemetría φ↑ en este tick
    pub fn should_sample_phi_up(&self) -> bool {
        (self.tick_counter - self.last_phi_up_tick) >= self.phi_up_interval
    }

    /// Avanza un tick del reloj
    pub fn step(&mut self, cond: &ClockConditions, sv: &StateVector) -> f64 {
        self.tick_counter += 1;
        self.select_mode(cond);
        let sigma = AbreathAxiom::sigma(sv); // Eq. 13
        let dt = self.compute_dt(sigma);
        if self.should_sample_phi_up() {
            self.last_phi_up_tick = self.tick_counter;
        }
        dt
    }
}
```

