```rust
// src/instantiation.rs
pub struct InstantiationGate {
    pub omega_checker: OmegaValidator,
    pub cgroup_bridge: CgroupV2Bridge,
}

impl InstantiationGate {
    pub fn register_unit(&self, spec: UnitSpec) -> Result<UnitHandle, InstantiationError> {
        // 1. Verificar Ω_A0/A0.1 (ética como estabilidad)
        if !self.omega_checker.check_purpose(&spec.purpose)? {
            return Err(InstantiationError::AxiomViolation("A0/A0.1"));
        }

        // 2. Asignar presupuesto físico (Ω_A3)
        let quota = self.cgroup_bridge.allocate(
            spec.cpu_weight, spec.memory_max, spec.io_weight
        )?;

        // 3. Configurar canales φ↑/φ↓
        let channels = Channels::new(
            spec.telemetry_schema,  // events.jsonl → Block B/C
            spec.params_schema,     // params.json ← Block E
        );

        // 4. Marcar como governed y retornar handle
        Ok(UnitHandle {
            id: spec.id,
            quota,
            channels,
            governed: true,
            lifecycle: Lifecycle::Testing,
        })
    }
}

