### Paso 3: Condicionamiento Operativo Gobernado
**Objetivo**: Someter la unidad a perturbaciones controladas para certificar trayectoria de recuperación.

```rust
// src/conditioning.rs
use crate::state_vector::StateVector;
use crate::perturbation::{PerturbationKind, PerturbationProfile};

pub struct OperationalConditioner {
    pub perturbation_profiles: Vec<PerturbationProfile>,
    pub recovery_validator: RecoveryValidator,
    pub dip_floor_threshold: f64,    // 0.942 para carga térmica cíclica
    pub tau_rec_max: f64,            // 30.0 segundos
}

pub struct ConditioningReport {
    pub successes: Vec<CertificationMetric>,
    pub failures: Vec<PerturbationKind>,
    pub overall_pass: bool,
}

pub struct CertificationMetric {
    pub kind: PerturbationKind,
    pub dip_floor: f64,
    pub tau_rec: f64,
    pub stasis_cos_final: f64,
}

impl OperationalConditioner {
    pub fn certify(&self, unit: &mut UnitHandle) -> ConditioningReport {
        let mut report = ConditioningReport {
            successes: Vec::new(),
            failures: Vec::new(),
            overall_pass: true,
        };

        for profile in &self.perturbation_profiles {
            // 1. Aplicar perturbación controlada
            unit.apply_perturbation(profile);

            // 2. Medir dip y recuperación
            let (dip_floor, tau_rec) = self.recovery_validator.measure(unit);

            // 3. Validar contra umbrales de viabilidad
            if dip_floor < 0.70 || tau_rec > self.tau_rec_max {
                report.failures.push(profile.kind);
                report.overall_pass = false;
                unit.trigger_degrade(); // A9: degrade ∨ abort
            } else {
                report.successes.push(CertificationMetric {
                    kind: profile.kind,
                    dip_floor,
                    tau_rec,
                    stasis_cos_final: unit.stasis_cos(),
                });
            }

            // 4. Reset para siguiente perfil
            unit.reset_to_stasis();
        }
        report
    }
}

